#[derive(Serialize, Deserialize)]
struct Envelope<T> {
    headers: HashMap<String, String>,
    payload: T,
}
let wire = serde_json::to_vec(&Envelope {
    headers: HashMap::from([("content-type".into(), "order/v2".into())]),
    payload: order,
})?;
// destination: unwrap once, then hand `payload` to the domain
let env: Envelope<Order> = serde_json::from_slice(&wire)?;
